// Indexes ODD numbers only: index i represents the value 2*i + 1.
vector<int> sieveOddOnly(int n) {
    vector<int> primes;
    if (n >= 2) primes.push_back(2);
    if (n < 3) return primes;

    int size = (n - 1) / 2;                 // odd values 3,5,7,... up to n
    vector<bool> comp(size + 1, false);     // 1 bit per entry
    for (int i = 1; 2 * i + 1 <= (int)sqrt((double)n); ++i) {
        if (comp[i]) continue;
        int p = 2 * i + 1;
        // first multiple with no smaller factor is p*p, and p*p is odd
        for (long long j = (long long)p * p; j <= n; j += 2LL * p)
            comp[(j - 1) / 2] = true;       // step 2p keeps us on odd multiples
    }
    for (int i = 1; i <= size; ++i)
        if (!comp[i]) primes.push_back(2 * i + 1);
    return primes;
}

long long primeProductInRange(long long L, long long R, long long M) {
    if (M == 1) return 0;                 // everything is 0 mod 1
    long long limit = (long long)sqrtl((long double)R) + 1;
    vector<bool> base(limit + 1, true);
    base[0] = base[1] = false;
    for (long long i = 2; i * i <= limit; ++i)
        if (base[i]) for (long long j = i * i; j <= limit; j += i) base[j] = false;

    vector<bool> win(R - L + 1, true);
    for (long long v = L; v <= min(R, 1LL); ++v) win[v - L] = false;
    for (long long p = 2; p <= limit; ++p) {
        if (!base[p]) continue;
        long long start = max(p * p, (L + p - 1) / p * p);
        for (long long j = start; j <= R; j += p) win[j - L] = false;
    }

    long long product = 1 % M;            // empty product is 1 (and 1 % 1 == 0)
    for (long long v = L; v <= R; ++v)
        if (win[v - L]) product = (product * (v % M)) % M;
    return product;
}

