def prime_product_in_range(L: int, R: int, M: int) -> int:
    if M == 1:
        return 0                       # everything is 0 mod 1
    limit = int(R ** 0.5) + 1
    base = [True] * (limit + 1)
    base[0] = base[1] = False
    i = 2
    while i * i <= limit:
        if base[i]:
            for j in range(i * i, limit + 1, i):
                base[j] = False
        i += 1

    win = [True] * (R - L + 1)
    for v in range(L, min(R, 1) + 1):
        win[v - L] = False
    for p in range(2, limit + 1):
        if not base[p]:
            continue
        for j in range(max(p * p, ((L + p - 1) // p) * p), R + 1, p):
            win[j - L] = False

    product = 1 % M                    # empty product is 1 (and 1 % 1 == 0)
    for v in range(L, R + 1):
        if win[v - L]:
            product = (product * (v % M)) % M
    return product

