    if M == 1:
        return 0                      # every residue collapses to 0
    a = ((a % M) + M) % M             # normalise, including negative a
    result = 1
    while b > 0:
        if b & 1:
            result = (result * a) % M
        a = (a * a) % M               # square for the next bit
        b >>= 1
    return result

