long long woodAt(const vector<long long>& trees, long long h) {
    long long total = 0;
    for (long long t : trees) if (t > h) total += t - h;
    return total;
}

long long maxSawHeight(const vector<long long>& trees, long long M) {
    long long lo = 0, hi = 0, best = 0;
    for (long long t : trees) hi = max(hi, t);
    while (lo <= hi) {
        long long mid = lo + (hi - lo) / 2;      // no overflow
        if (woodAt(trees, mid) >= M) {           // feasible: try to cut higher
            best = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return best;
}

