def wood_at(trees: list[int], h: int) -> int:
    """Wood harvested if the saw is set to height h."""
    return sum(t - h for t in trees if t > h)


def max_saw_height(trees: list[int], M: int) -> int:
    lo, hi, best = 0, max(trees), 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if wood_at(trees, mid) >= M:      # feasible: try to cut higher
            best = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return best

