def check_strict_weak_ordering(cmp, samples: list) -> list[str]:
    """Return the rules cmp violates on samples (empty list == valid)."""
    broken = []
    if any(cmp(a, a) for a in samples):
        broken.append("irreflexive")
    if any(cmp(a, b) and cmp(b, a) for a in samples for b in samples):
        broken.append("asymmetric")
    for a in samples:
        for b in samples:
            for c in samples:
                if cmp(a, b) and cmp(b, c) and not cmp(a, c):
                    broken.append("transitive")
                    return broken
    return broken


def sort_items(items: list[tuple]) -> list[tuple]:
    """(score, id) -> higher score first, then lower id. Strict on every key."""
    return sorted(items, key=lambda it: (-it[0], it[1]))
